import csv
from pathlib import Path

from attendance import as_utc, load
from datetime import datetime


def _instant(value):
    return datetime.fromisoformat(value.replace("Z", "+00:00"))


def normalize(rows):
    """One row per (badge, session): the latest observation by instant; cancelled pairs dropped."""
    latest = {}
    for row in rows:
        key = (row["badge"], row["session"])
        seen = latest.get(key)
        if seen is None or _instant(row["observed_at"]) > _instant(seen["observed_at"]):
            latest[key] = row
        elif _instant(row["observed_at"]) == _instant(seen["observed_at"]):
            raise ValueError(f"tie on latest observation for {key}")
    return [{"badge": b, "session": s, "start_utc": as_utc(r["started_at"])}
            for (b, s), r in sorted(latest.items()) if r["status"] != "cancelled"]


def write(rows, path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=["badge", "session", "start_utc"])
        writer.writeheader()
        writer.writerows(rows)


if __name__ == "__main__":
    write(normalize(load()), "build/normalized.csv")
EOF
